class PartialResult:
    def __init__(self, text, is_final):
        self.text = text
        self.is_final = is_final

def handle_partial_results(event):
    results = []
    for result in event.transcript.results:
        results.append(PartialResult(result.alternatives[0].transcript, not result.is_partial))
    return results

import boto3

def get_transcribe_client(region=None):
    return boto3.client('transcribe', region_name=region or 'us-east-1')

def get_translate_client(region=None):
    return boto3.client('translate', region_name=region or 'us-east-1')

def get_comprehend_client(region=None):
    return boto3.client('comprehend', region_name=region or 'us-east-1')

def get_polly_client(region=None):
    return boto3.client('polly', region_name=region or 'us-east-1')

class TranscriptionRequest:
    def __init__(self, language_code, sample_rate_hz, audio_chunks):
        self.language_code = language_code
        self.sample_rate_hz = sample_rate_hz
        self.audio_chunks = audio_chunks

class TranscriptionResponse:
    def __init__(self, text, is_final):
        self.text = text
        self.is_final = is_final

def normalize_transcription_response(response):
    return TranscriptionResponse(response['text'], response['is_final'])
